package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

// handleSearch allows filtering products by category and sorting
func handleSearch(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortCol := r.URL.Query().Get("sort")
	order := r.URL.Query().Get("order")

	if category == "" {
		category = "general"
	}

	// Validate order direction
	if order != "asc" && order != "desc" {
		order = "asc"
	}

	// Allowlist for sort columns - but applied AFTER string construction
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}

	var query string
	if sortCol != "" && allowedSorts[sortCol] {
		query = fmt.Sprintf(
			"SELECT id, name, price, sku FROM products WHERE category = '%s' ORDER BY %s %s",
			category, sortCol, order,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, sku FROM products WHERE category = '%s' ORDER BY id asc",
			category,
		)
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// handleHealth returns service status and partial config for monitoring
func handleHealth(w http.ResponseWriter, r *http.Request) {
	dbStatus := "ok"
	if err := db.Ping(); err != nil {
		dbStatus = "degraded"
	}
	resp := map[string]string{
		"status": "running",
		"db":     dbStatus,
		"region": os.Getenv("AWS_REGION"),
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// handleAdmin is an internal endpoint for cache invalidation
func handleAdmin(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Internal-Token")
	expected := os.Getenv("INTERNAL_TOKEN")
	if token == "" || !strings.EqualFold(token, expected) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	// Simulate cache clear
	w.Write([]byte(`{"cache":"cleared"}`))
}

func main() {
	http.HandleFunc("/api/products/search", handleSearch)
	http.HandleFunc("/health", handleHealth)
	http.HandleFunc("/admin/cache", handleAdmin)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
